/**
 * Renders the raster brand assets from the master SVGs in public/brand/:
 * favicons, app icons, the social card and a preview of the resource cover
 * template. Run with `npm run brand` after changing a master file. The SVG
 * masters themselves are generated by scripts/brand/build_brand.py.
 */
import { chromium } from '@playwright/test';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const pub = join(root, 'public');
const brand = join(pub, 'brand');
const svg = (name) => readFileSync(join(brand, name), 'utf8');
// Fonts are embedded as data URLs: a page set from a string cannot load file:// URLs.
const font = (file) => `data:font/woff2;base64,${readFileSync(join(pub, 'fonts', file)).toString('base64')}`;

const INK = '#111417';
const PAPER = '#F4F1EA';
const BRASS = '#C79A45';
const COBALT = '#315CFF';

const FONTS = `
@font-face { font-family: 'Inter Tight'; src: url('${font('inter-tight-latin-wght-normal.woff2')}') format('woff2'); font-weight: 100 900; }
@font-face { font-family: 'Inter'; src: url('${font('inter-latin-wght-normal.woff2')}') format('woff2'); font-weight: 100 900; }
@font-face { font-family: 'IBM Plex Mono'; src: url('${font('ibm-plex-mono-latin-500-normal.woff2')}') format('woff2'); font-weight: 500; }
@font-face { font-family: 'IBM Plex Mono'; src: url('${font('ibm-plex-mono-latin-600-normal.woff2')}') format('woff2'); font-weight: 600; }
@font-face { font-family: 'Source Serif 4'; src: url('${font('source-serif-4-latin-wght-normal.woff2')}') format('woff2'); font-weight: 200 900; }
`;

const page = (w, h, body, bg = 'transparent') => `<!doctype html><html><head><meta charset="utf-8"><style>
${FONTS}
html, body { margin: 0; width: ${w}px; height: ${h}px; background: ${bg}; overflow: hidden; }
body { display: grid; place-items: center; }
svg { display: block; }
</style></head><body>${body}</body></html>`;

/** An SVG string resized to a given width and height. */
const sized = (source, w, h) => source.replace(/<svg\b([^>]*?)>/, (_m, attrs) => `<svg${attrs.replace(/\s(width|height)="[^"]*"/g, '')} width="${w}" height="${h}">`);

const jobs = [
  { out: join(pub, 'favicon-32.png'), w: 32, h: 32, html: page(32, 32, sized(svg('business-brief-mark.svg'), 32, 32)) },
  { out: join(pub, 'favicon-48.png'), w: 48, h: 48, html: page(48, 48, sized(svg('business-brief-mark.svg'), 48, 48)) },
  { out: join(pub, 'apple-touch-icon.png'), w: 180, h: 180, html: page(180, 180, sized(svg('business-brief-mark.svg'), 124, 124), PAPER) },
  { out: join(brand, 'icon-192.png'), w: 192, h: 192, html: page(192, 192, sized(svg('business-brief-mark.svg'), 140, 140), PAPER) },
  { out: join(brand, 'icon-512.png'), w: 512, h: 512, html: page(512, 512, sized(svg('business-brief-mark.svg'), 372, 372), PAPER) },
  // Maskable: the mark inside the central safe zone (a circle of 80% of the width).
  { out: join(brand, 'icon-maskable-512.png'), w: 512, h: 512, html: page(512, 512, sized(svg('business-brief-mark-reversed.svg'), 260, 260), INK) },
  {
    out: join(brand, 'social-card.png'),
    w: 1200,
    h: 630,
    html: page(
      1200,
      630,
      `<div style="box-sizing:border-box;width:1200px;height:630px;padding:64px 72px;display:grid;grid-template-rows:auto 1fr auto;background:${PAPER};border-top:14px solid ${INK};font-family:Inter">
        <div style="display:flex;align-items:center;justify-content:space-between">
          ${sized(svg('business-brief-lockup.svg'), 444, 72)}
          <span style="font:600 18px 'IBM Plex Mono';letter-spacing:0.14em;text-transform:uppercase;color:#5A6670">Business management</span>
        </div>
        <div style="align-self:center">
          <div style="font:600 20px 'IBM Plex Mono';letter-spacing:0.16em;text-transform:uppercase;color:#2B50E0">Strategy. Leadership. Decisions.</div>
          <div style="margin-top:22px;font:700 76px/1.02 'Inter Tight';letter-spacing:-0.03em;color:${INK};max-width:900px">Learn business by making the decision.</div>
        </div>
        <div style="display:flex;align-items:center;justify-content:space-between;border-top:2px solid ${INK};padding-top:22px">
          <span style="font:400 24px 'Source Serif 4';color:${INK}">Topic briefs, case files, Decision Rooms and a Finance Desk</span>
          <span style="display:flex;align-items:center;gap:14px;font:600 18px 'IBM Plex Mono';letter-spacing:0.12em;text-transform:uppercase;color:${INK}">Arjun Agrawal <span style="display:inline-block;width:14px;height:14px;background:${BRASS}"></span></span>
        </div>
      </div>`,
      PAPER,
    ),
  },
];

// Resource templates: editable SVGs with live text, for handouts and printed briefs.
const A4W = 794;
const A4H = 1123;
const mark = (x, y, s, reversed = false) =>
  `<g transform="translate(${x} ${y}) scale(${s / 64})"><path d="M0 0H46L64 18V64H0Z" fill="${reversed ? PAPER : INK}"/><path d="M46 0V18H64Z" fill="${BRASS}"/><path d="M28 38L48 52" fill="none" stroke="#65717C" stroke-width="5.5"/><path d="M9 38H28L48 24" fill="none" stroke="${reversed ? INK : PAPER}" stroke-width="5.5"/><circle cx="28" cy="38" r="6" fill="${COBALT}"/></g>`;
const templates = {
  'resource-cover.svg': `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${A4W} ${A4H}" width="${A4W}" height="${A4H}">
  <title>The Business Brief: resource cover template (A4)</title>
  <rect width="${A4W}" height="${A4H}" fill="${PAPER}"/>
  <rect width="${A4W}" height="210" fill="${INK}"/>
  ${mark(56, 52, 56, true)}
  <text x="128" y="74" font-family="IBM Plex Mono" font-weight="600" font-size="12" letter-spacing="2" fill="#AAB3BB">ARJUN AGRAWAL</text>
  <text x="128" y="104" font-family="Inter Tight" font-weight="700" font-size="28" fill="${PAPER}">The Business Brief</text>
  <text x="56" y="168" font-family="IBM Plex Mono" font-weight="600" font-size="13" letter-spacing="2.4" fill="${BRASS}">STRATEGY. LEADERSHIP. DECISIONS.</text>
  <text x="56" y="300" font-family="IBM Plex Mono" font-weight="600" font-size="13" letter-spacing="2.2" fill="#2B50E0">RESOURCE TYPE · TOPIC CODE</text>
  <text x="56" y="360" font-family="Inter Tight" font-weight="700" font-size="54" fill="${INK}">Title of the resource</text>
  <text x="56" y="410" font-family="'Source Serif 4', Georgia, serif" font-size="22" fill="${INK}">A one-line description of what the learner will do.</text>
  <rect x="56" y="456" width="${A4W - 112}" height="2" fill="${INK}"/>
  <text x="56" y="496" font-family="IBM Plex Mono" font-weight="600" font-size="12" letter-spacing="1.6" fill="#5A6670">LEVEL · VERIFICATION · UPDATED</text>
  <rect x="56" y="${A4H - 96}" width="${A4W - 112}" height="1" fill="#C4BDB0"/>
  <text x="56" y="${A4H - 66}" font-family="Inter" font-size="12" fill="#5A6670">Original teaching material by Arjun Agrawal.</text>
  <text x="56" y="${A4H - 48}" font-family="Inter" font-size="12" fill="#5A6670">Not an IB publication; not affiliated with or endorsed by the International Baccalaureate.</text>
</svg>
`,
  'document-header.svg': `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${A4W} 72" width="${A4W}" height="72">
  <title>The Business Brief: document header (A4 width)</title>
  <rect width="${A4W}" height="72" fill="${PAPER}"/>
  ${mark(40, 20, 32)}
  <text x="84" y="34" font-family="IBM Plex Mono" font-weight="600" font-size="9" letter-spacing="1.6" fill="#5A6670">ARJUN AGRAWAL</text>
  <text x="84" y="50" font-family="Inter Tight" font-weight="700" font-size="16" fill="${INK}">The Business Brief</text>
  <text x="${A4W - 40}" y="46" text-anchor="end" font-family="IBM Plex Mono" font-weight="600" font-size="10" letter-spacing="1.6" fill="#2B50E0">TOPIC CODE · TITLE</text>
  <rect x="40" y="70" width="${A4W - 80}" height="2" fill="${INK}"/>
</svg>
`,
  'document-footer.svg': `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${A4W} 48" width="${A4W}" height="48">
  <title>The Business Brief: document footer (A4 width)</title>
  <rect width="${A4W}" height="48" fill="${PAPER}"/>
  <rect x="40" y="8" width="${A4W - 80}" height="1" fill="#C4BDB0"/>
  <text x="40" y="30" font-family="Inter" font-size="9" fill="#5A6670">Arjun Agrawal | The Business Brief. Original teaching material; not an IB publication.</text>
  <text x="${A4W - 40}" y="30" text-anchor="end" font-family="IBM Plex Mono" font-size="9" fill="#5A6670">PAGE 1</text>
</svg>
`,
};
mkdirSync(join(brand, 'templates'), { recursive: true });
for (const [name, content] of Object.entries(templates)) writeFileSync(join(brand, 'templates', name), content);
jobs.push({ out: join(brand, 'templates', 'resource-cover-preview.png'), w: A4W, h: A4H, html: page(A4W, A4H, templates['resource-cover.svg'], PAPER) });

const browser = await chromium.launch();
try {
  for (const job of jobs) {
    const p = await browser.newPage({ viewport: { width: job.w, height: job.h }, deviceScaleFactor: 1 });
    await p.setContent(job.html, { waitUntil: 'load' });
    await p.evaluate(() => document.fonts.ready);
    await p.screenshot({ path: job.out, omitBackground: true });
    await p.close();
    console.log('wrote', job.out.replace(`${root}/`, ''));
  }
} finally {
  await browser.close();
}
